// ❌ OLD: Manual state management for loading, inputs, and form submission.
import { useState } from 'react';

function SubmitButton({ loading }) {
  return <button disabled={loading}>{loading ? 'Saving...' : 'Save'}</button>;
}

export default function FormLegacy({ onSave }) {
  const [name, setName] = useState('');
  const [loading, setLoading] = useState(false);

  async function handleSubmit(e) {
    e.preventDefault();
    setLoading(true);
    try {
      await onSave(name);
    } finally {
      setLoading(false);
    }
  }

  return (
    <form onSubmit={handleSubmit}>
      <input value={name} onChange={(e) => setName(e.target.value)} />
      <SubmitButton loading={loading} />
    </form>
  );
}

// ✅ NEW: React 19 passes FormData automatically and useFormStatus tracks pending state.
import { useFormStatus } from 'react-dom';

function SubmitButton() {
  // Reads status directly from the parent <form> without props:
  const { pending } = useFormStatus();
  return <button disabled={pending}>{pending ? 'Saving...' : 'Save'}</button>;
}

export default function FormModern({ saveAction }) {
  return (
    <form action={saveAction}>
      <input name="userName" required />
      <SubmitButton />
    </form>
  );
}
